<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\Authentication\Application\ActiveUserFindService;
use Civi\Lughauth\Features\OAuth\Session\Domain\SessionInfo;
use Civi\Lughauth\Features\OAuth\Session\Domain\Gateway\SessionStoreGateway;

final class ActiveUserFindServiceUnitTest extends TestCase
{
    private function makeStore(?SessionInfo $info, ?string $csidToSessionId = null): SessionStoreGateway
    {
        return new class($info, $csidToSessionId) implements SessionStoreGateway {
            public function __construct(private ?SessionInfo $info, private ?string $csidSessionId) {}
            public function loadSession(string $state): ?SessionInfo { return $this->info; }
            public function findActiveSessionIdByCsid(string $csid): ?string { return $this->csidSessionId; }
            public function saveSession(string $s, \Civi\Lughauth\Features\OAuth\Client\Domain\ClientData $c, string $iss, \Civi\Lughauth\Features\OAuth\Authentication\Domain\ChallengesState $k, \Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult $v, string $csid, \DateInterval $exp): void {}
            public function updateSession(string $n, string $o): void {}
            public function deleteSession(string $s): void {}
            public function purgeExpired(): void {}
        };
    }

    public function test_find_by_session_id_returns_active_user(): void
    {
        $session = new SessionInfo('csid-1', true, 'https://iss', 'user-1', 'client-1');
        $service = new ActiveUserFindService($this->makeStore($session));

        $user = $service->findBySessionId('sess-abc');

        $this->assertNotNull($user);
        $this->assertSame('sess-abc', $user->sessionId);
        $this->assertSame('user-1', $user->userId);
        $this->assertSame('client-1', $user->clientId);
        $this->assertSame('https://iss', $user->issuer);
        $this->assertSame('csid-1', $user->csid);
        $this->assertTrue($user->withMfa);
    }

    public function test_find_by_session_id_returns_null_when_not_found(): void
    {
        $service = new ActiveUserFindService($this->makeStore(null));
        $this->assertNull($service->findBySessionId('missing'));
    }

    public function test_find_by_csid_returns_active_user(): void
    {
        $session = new SessionInfo('csid-9', false, 'https://iss', 'user-2', 'c-2');
        $service = new ActiveUserFindService($this->makeStore($session, 'sess-via-csid'));

        $user = $service->findByCsid('csid-9');

        $this->assertNotNull($user);
        $this->assertSame('sess-via-csid', $user->sessionId);
    }

    public function test_find_by_csid_returns_null_when_no_session_id(): void
    {
        $service = new ActiveUserFindService($this->makeStore(null, null));
        $this->assertNull($service->findByCsid('unknown-csid'));
    }
}
